435	wysiwyg	\N	f	\N	"{\\n  \\"html\\":\\"\\u0026lt;p\\u0026gt;Na uvedenou pozici hledáme zájemce o práci. Jedná se o práci přebalování sortimentu do spotřebitelských balení.\\u0026lt;/p\\u0026gt;\\u0026lt;p\\u0026gt;\\u0026lt;strong\\u0026gt;JEDNÁ SE O VYHRANĚNÉ MÍSTO PRO OZP (invalidní důchodce/osoby zdravotně znevýhodněné)\\u0026lt;/strong\\u0026gt;\\u0026lt;/p\\u0026gt;\\"\\n}\\n"	2021-11-04 14:16:33.381694	2021-11-04 14:20:06.573458
